     */
    var `route`: kotlin.String?
    , 
    /**
     * Why Relay couldn't reach it the last time it tried, in words.
     */
    var `problem`: kotlin.String?
    , 
    /**
     * The capabilities granted to it here (N5): none until the person
     * turns one on for it.
     */
