/**
 * Every error a command returns. `reason`/`detail` are diagnostics, not UI
 * copy. (No field is called `message`: it clashes with Kotlin's
 * `Throwable.message`.)
 */
sealed class ChatException: kotlin.Exception() {
    
    class Network(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Certificate(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Http(
        
        val `status`: kotlin.UShort, 
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "status=${ `status` }, reason=${ `reason` }"
    }
    
    class BadResponse(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Cancelled(
        ) : ChatException() {
        override val message
            get() = ""
    }
    
    class NotFound(
        
        val `conversationId`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "conversationId=${ `conversationId` }"
    }
    
    class UnsupportedOnHost(
        
        val `detail`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * No account yet: call `sign_up` first.
     */
    class NotSignedIn(
        ) : ChatException() {
        override val message
            get() = ""
    }
    
    /**
     * The server rejected the account token (HTTP 401).
     */
    class Unauthorized(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The Keychain or the chat store could not be used.
     */
    class Storage(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Another core already has this data folder open.
     */
    class InUse(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class ShutDown(
        ) : ChatException() {
        override val message
            get() = ""
    }
    
    class Internal(
        
        val `reason`: kotlin.String
        ) : ChatException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ChatException> {
        override fun lift(error_buf: RustBuffer.ByValue): ChatException = FfiConverterTypeChatError.lift(error_buf)
    }

    
}

