/**
 * Where a send with a code has got. The app shows it and, while there is a
 * code, advertises `number`, `port` and `endpoint_id` with Bonjour
 * (`CODE_SERVICE_TYPE`, TXT `v=1`, `n` = number, `id` = endpoint id).
 */
sealed class CodeSend {
    
    object Idle : CodeSend()
    
    
    /**
     * Hashing the file.
     */
    data class Preparing(
        val `name`: kotlin.String, 
        val `size`: kotlin.ULong) : CodeSend()
        
    {
        

        companion object
    }
    
    /**
     * The code is ready for the receiver. `note` says why the code changed,
     * when it did.
     */
    data class Waiting(
        val `code`: kotlin.String, 
        val `number`: kotlin.UByte, 
        val `port`: kotlin.UShort, 
        val `endpointId`: kotlin.String, 
        val `name`: kotlin.String, 
        val `size`: kotlin.ULong, 
        val `note`: kotlin.String?) : CodeSend()
        
    {
        

        companion object
    }
    
    /**
     * A receiver proved the code and is fetching the file.
     */
    data class Sending(
        val `code`: kotlin.String, 
        val `number`: kotlin.UByte, 
        val `port`: kotlin.UShort, 
        val `endpointId`: kotlin.String, 
        val `name`: kotlin.String, 
        val `size`: kotlin.ULong) : CodeSend()
        
    {
        

        companion object
    }
    
    /**
     * The receiver has the file, verified and saved.
     */
    data class Sent(
        val `name`: kotlin.String, 
        val `size`: kotlin.ULong, 
        val `seconds`: kotlin.Double, 
        val `megabytesPerSecond`: kotlin.Double) : CodeSend()
        
    {
        

        companion object
    }
    
    data class Failed(
        val `reason`: kotlin.String) : CodeSend()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

