/**
 * The kind of route an address, or a connection, uses.
 */

enum class RouteKind {
    
    /**
     * The same local network (Wi-Fi or Ethernet at home).
     */
    LOCAL,
    /**
     * A private network between the devices, such as Tailscale.
     */
    PRIVATE,
    /**
     * Directly over the internet.
     */
    INTERNET,
    /**
     * Through a relay server (none yet: PR 7).
     */
    RELAY;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeRouteKind: FfiConverterRustBuffer<RouteKind> {
    override fun read(buf: ByteBuffer) = try {
        RouteKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: RouteKind) = 4UL

    override fun write(value: RouteKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
