        val `done`: kotlin.ULong) : TransferStatus()
        
    {
        

        companion object
    }
    
    object Done : TransferStatus()
    
    
    data class Failed(
        val `reason`: kotlin.String) : TransferStatus()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

